/* "Other" types show what was typed */
const typeText=a=>a.asset_type==="Other"&&a.asset_type_other?`Other · ${a.asset_type_other}`:(a.asset_type||"");
const visitTypeText=v=>v.visit_type==="Other"&&v.visit_type_other?`Other · ${v.visit_type_other}`:(v.visit_type||"");
const FREQ={"Monthly":1,"Quarterly":3,"Half yearly":6,"Yearly":12};
