let AFTER_SUBMIT=["vendor_contact","vendor_phone","vendor_email","notes","renewal_status","remind_before_days"];   // contract fields that stay editable after submit
const RENEWAL=["Not started","Quotation requested","Quotation received","WO issued","Renewed","Not renewing"];
const PAY_TERMS=["100% advance","Half yearly","Quarterly","Monthly","On completion"];

/* ============ link targets (mock of ERPNext / site records; real ones are confirmed in Step 0) ============ */
let COMPANIES=["GHREMF Society Pune","GH Raisoni College Of Engineering And Management Nagpur"];
