const blankAsset=()=>({id:"",asset_name:"",asset_type:"",asset_type_other:"",capacity:"",make:"",model:"",serial_no:"",campus:"",site_building:"",exact_location:"",asset_status:"In use",supplier:"",purchase_order:"",purchase_invoice:"",purchase_date:"",installation_date:"",purchase_cost:null,expected_life_years:null,erpnext_asset:"",warranty_start:"",warranty_end:"",warranty_provider:"",warranty_terms:"",attachments:[],changes:[]});
const blankContract=()=>({id:"",docstatus:0,work_order:"",vendor:"",vendor_contact:"",vendor_phone:"",vendor_email:"",quotation_ref:"",wo_date:"",contract_type:"",assets:[],start_date:"",end_date:"",remind_before_days:60,value_excl_gst:null,gst_percent:18,payment_terms:"",yearly_escalation_percent:null,visit_frequency:"",visits_per_year:null,extra_visit_charge:null,breakdown_response:"",scope:"",exclusions:"",notes:"",documents:[],renewal_status:"Not started",previous_contract:"",next_contract:""});
const blankVisit=()=>({id:"",asset:"",amc_contract:"",visit_type:"Preventive",visit_type_other:"",status:"Planned",planned_date:"",done_date:"",engineer:"",hours_on_site:null,work_done:"",parts_replaced:"",readings_remarks:"",next_action:"",extra_charge:null,service_report:""});


/* ============ controller logic (this is what the Python controllers will do) ============ */
function contractStatus(c){
  const s=daysTo(c.start_date),e=daysTo(c.end_date);
  if(s==null||e==null)return {status:"",days:null};
  if(s>0)return {status:"Upcoming",days:e};
  if(e<0)return {status:"Expired",days:e};
  if(e<=EXPIRING_DAYS)return {status:"Expiring",days:e};
  return {status:"Active",days:e};
}
function warrantyStatus(a){
  if(!a.warranty_end)return "Not recorded";
  const d=daysTo(a.warranty_end);
  return d<0?"Expired":d<=WARRANTY_DAYS?"Expiring":"Under warranty";
}
const isOverdue=v=>v.status==="Planned"&&!!v.planned_date&&v.planned_date<TODAY_S;
const submitted=()=>DB.contracts.filter(c=>c.docstatus===1);
const contractsFor=id=>submitted().filter(c=>(c.assets||[]).some(r=>r.asset===id));
const assetById=id=>DB.assets.find(a=>a.id===id);
const contractById=id=>DB.contracts.find(c=>c.id===id);
const visitsFor=id=>DB.visits.filter(v=>v.asset===id);
const total_incl=c=>r2((+c.value_excl_gst||0)*(1+(+c.gst_percent||0)/100));

function assetAmcState(a){
  const list=contractsFor(a.id).slice().sort((x,y)=>(parseD(y.end_date)||0)-(parseD(x.end_date)||0));
  const cur=list.find(c=>{const s=contractStatus(c).status;return s==="Active"||s==="Expiring"});
  if(cur){const st=contractStatus(cur);return {contract:cur.id,status:st.status,days:st.days}}
  const up=list.filter(c=>contractStatus(c).status==="Upcoming").sort((x,y)=>parseD(x.start_date)-parseD(y.start_date))[0];
  if(up)return {contract:up.id,status:"Upcoming",days:contractStatus(up).days};
  if(list.length)return {contract:list[0].id,status:"Expired",days:contractStatus(list[0]).days};
  return {contract:"",status:"No AMC",days:null};
}
function costOfOwnership(a){
  const purchase=+a.purchase_cost||0;
  const amc=contractsFor(a.id).reduce((s,c)=>s+total_incl(c)/Math.max(1,(c.assets||[]).length),0);
  const visits=visitsFor(a.id).reduce((s,v)=>s+(+v.extra_charge||0),0);
  return {purchase,amc:r2(amc),visits:r2(visits),total:r2(purchase+amc+visits)};
}
function recompute(){
  DB.contracts.forEach(c=>{c.total_incl_gst=total_incl(c);const st=contractStatus(c);c.contract_status=st.status;c.days_left=st.days});
  DB.visits.forEach(v=>{v.is_overdue=isOverdue(v)?1:0});
  DB.assets.forEach(a=>{
    a.warranty_status=warrantyStatus(a);
    const am=assetAmcState(a);a.current_amc=am.contract;a.amc_status=am.status;a.amc_days_left=am.days;
    const vs=visitsFor(a.id);
    a.last_visit_date=vs.filter(v=>v.status==="Done").map(v=>v.done_date||v.planned_date).sort().pop()||"";
    a.next_visit_date=vs.filter(v=>v.status==="Planned").map(v=>v.planned_date).sort()[0]||"";
    a.total_cost_of_ownership=costOfOwnership(a).total;
  });
}


/* ============ roles ============ */
const ROLE_PERMS={
  "AMC Manager":{asset:"crud",contract:"crudsx".replace("x",""),visit:"crud"},
  "Maintenance User":{asset:"r",contract:"r",visit:"cru"},
  "Campus Viewer":{asset:"r",contract:"r",visit:"r"}
};
let ROLE="AMC Manager",VIEW_CAMPUS=COMPANIES[0],PERMS={};
const can=(dt,act)=>((CFG.proto?ROLE_PERMS[ROLE][dt]:PERMS[dt])||"").includes(act);
const scoped=()=>CFG.proto&&ROLE==="Campus Viewer";
const A=()=>scoped()?DB.assets.filter(a=>a.campus===VIEW_CAMPUS):DB.assets;
const C=()=>{
  if(!scoped())return DB.contracts;
  return DB.contracts.filter(c=>(c.assets||[]).some(r=>{const a=assetById(r.asset);return a&&a.campus===VIEW_CAMPUS}));
};
const V=()=>{
  if(!scoped())return DB.visits;
  return DB.visits.filter(v=>{const a=assetById(v.asset);return a&&a.campus===VIEW_CAMPUS});
};
const campusesOf=list=>[...new Set(list.map(a=>a.campus).filter(Boolean))].sort();

