/* ============ asset page + history ============ */
function historyEvents(a){
  const ev=[],cs=contractsFor(a.id),vs=visitsFor(a.id);
  if(a.purchase_date)ev.push({d:a.purchase_date,dot:"var(--brand)",t:"Purchased",s:[a.supplier&&`from ${a.supplier}`,a.purchase_cost&&inr(a.purchase_cost),a.purchase_order&&`PO ${a.purchase_order}`,a.purchase_invoice&&`Invoice ${a.purchase_invoice}`].filter(Boolean).join(" · "),open:"erp:"+(a.purchase_order||a.purchase_invoice||"")});
  if(a.installation_date)ev.push({d:a.installation_date,dot:"var(--brand)",t:"Installed",s:[a.site_building,a.exact_location].filter(Boolean).join(" · "),open:"edit:"+a.id});
  if(a.warranty_start)ev.push({d:a.warranty_start,dot:"var(--brand)",t:"Warranty started",s:a.warranty_provider||"",open:"edit:"+a.id});
  if(a.warranty_end){const d=daysTo(a.warranty_end);ev.push({d:a.warranty_end,dot:`var(--${d<0?"exp":d<=60?"warn":"ok"})`,t:d<0?"Warranty ended":"Warranty ends",s:a.warranty_provider||"",open:"edit:"+a.id})}
  cs.forEach(c=>{
    ev.push({d:c.start_date,dot:"var(--ok)",t:`AMC started · ${c.vendor}`,s:[c.work_order,inr(c.total_incl_gst)+" incl. GST",c.visit_frequency&&`${c.visit_frequency} visits`].filter(Boolean).join(" · "),open:"contract:"+c.id});
    const d=daysTo(c.end_date);ev.push({d:c.end_date,dot:`var(--${d<0?"exp":bandOf(d)==="ok"?"ok":bandOf(d)==="warn"?"warn":"bad"})`,t:`${d<0?"AMC ended":"AMC ends"} · ${c.vendor}`,s:`${c.id} · renewal: ${c.renewal_status}`,open:"contract:"+c.id});
  });
  vs.forEach(v=>{if(v.status==="Cancelled")return;
    const dot=v.status==="Done"?"var(--ok)":v.status==="Missed"||v.is_overdue?"var(--bad)":"var(--brand)";
    ev.push({d:v.status==="Done"?(v.done_date||v.planned_date):v.planned_date,dot,t:`${visitTypeText(v)} · ${v.status==="Planned"&&v.is_overdue?"Overdue":v.status}`,s:[v.engineer,v.work_done,v.parts_replaced&&`Parts: ${v.parts_replaced}`,v.extra_charge&&inr(v.extra_charge)].filter(Boolean).join(" · "),open:"visit:"+v.id});
  });
  ev.forEach(e=>e.future=e.d>TODAY_S);
  ev.sort((x,y)=>y.d.localeCompare(x.d));
  return ev;
}
function historyHTML(a){
  const ev=historyEvents(a);
  if(!ev.length)return `<div class="empty">No history yet. Add purchase details, an AMC or a visit.</div>`;
  let h="",marked=false;
  ev.forEach(e=>{
    if(!e.future&&!marked){h+=`<li class="todaymark">Today · ${fmtD(TODAY_S)}</li>`;marked=true}
    h+=`<li class="${e.future?"future":""}" style="--dot:${e.dot}" ${e.open&&e.open!=="erp:"?`data-open="${esc(e.open)}" tabindex="0"`:""}><div class="hd">${fmtD(e.d)}</div><div class="ht">${esc(e.t)}</div>${e.s?`<div class="hs">${esc(e.s)}</div>`:""}</li>`;
  });
  if(!marked)h+=`<li class="todaymark">Today · ${fmtD(TODAY_S)}</li>`;
  return `<ul class="hist">${h}</ul>`;
}
