/* ============ script reports ============ */
function reportRows(kind){
  const f=ST.rep[kind];
  const okAsset=a=>a&&(!f.campus||a.campus===f.campus)&&(!f.type||a.asset_type===f.type);
  if(kind==="coverage"){
    return A().filter(okAsset).map(a=>{const d=a.amc_days_left,st=a.amc_status;
      const cls=st==="Expired"?"bad":(st==="Active"||st==="Expiring")?bandOf(d):"";
      return {cls,cells:[`<a href="#asset/${esc(a.id)}">${esc(a.id)}</a>`,esc(a.asset_name),esc(typeText(a)),esc(a.campus),amcPill(st,d),esc(vendorOf(a)||"–"),a.current_amc&&contractById(a.current_amc)?fmtD(contractById(a.current_amc).end_date):"–",warPill(a),a.last_visit_date?fmtD(a.last_visit_date):"–",a.next_visit_date?fmtD(a.next_visit_date):"–"],
        csv:[a.id,a.asset_name,typeText(a),a.campus,a.amc_status,vendorOf(a),a.current_amc&&contractById(a.current_amc)?contractById(a.current_amc).end_date:"",a.warranty_status,a.last_visit_date,a.next_visit_date],sort:d==null?99999:d}}).sort((x,y)=>x.sort-y.sort);
  }
  if(kind==="renewals"){
    const out=[];
    C().filter(c=>c.docstatus===1).forEach(c=>{const as=(c.assets||[]).map(r=>assetById(r.asset)).filter(Boolean);if(!as.some(okAsset))return;const d=c.days_left;
      if(d!=null&&((d>=0&&d<=f.days)||(f.expired&&d<0&&!["Renewed","Not renewing"].includes(c.renewal_status))))
        out.push({cls:bandOf(d),sort:d,cells:["AMC",`<a href="#" data-open="contract:${esc(c.id)}">${esc(c.id)}</a>`,esc(as.map(a=>a.asset_name).join(", ")),esc([...new Set(as.map(a=>a.campus))].join(", ")),esc(c.vendor),fmtD(c.end_date),d<0?`${-d}d ago`:`${d}d`,pill("info",c.renewal_status),inr(c.total_incl_gst)],csv:["AMC",c.id,as.map(a=>a.asset_name).join("; "),[...new Set(as.map(a=>a.campus))].join("; "),c.vendor,c.end_date,d,c.renewal_status,c.total_incl_gst]})});
    A().filter(okAsset).forEach(a=>{if(!a.warranty_end)return;const d=daysTo(a.warranty_end);
      if((d>=0&&d<=f.days)||(f.expired&&d<0&&d>=-180))out.push({cls:bandOf(d),sort:d,cells:["Warranty",`<a href="#asset/${esc(a.id)}">${esc(a.id)}</a>`,esc(a.asset_name),esc(a.campus),esc(a.warranty_provider||a.supplier||"–"),fmtD(a.warranty_end),d<0?`${-d}d ago`:`${d}d`,"–","–"],csv:["Warranty",a.id,a.asset_name,a.campus,a.warranty_provider||a.supplier||"",a.warranty_end,d,"",""]})});
    return out.sort((x,y)=>x.sort-y.sort);
  }
  // vsched
  return V().filter(v=>{const a=assetById(v.asset);if(!okAsset(a))return false;if(v.is_overdue)return true;const d=daysTo(v.planned_date);return v.status==="Planned"&&d>=0&&d<=f.days}).sort((x,y)=>x.planned_date.localeCompare(y.planned_date)).map(v=>{
    const a=assetById(v.asset),d=daysTo(v.planned_date),cls=v.is_overdue?"bad":d<=VISIT_ALERT_DAYS?"warn":"";
    return {cls,cells:[fmtD(v.planned_date),`<a href="#" data-open="visit:${esc(v.id)}">${esc(v.id)}</a>`,`<a href="#asset/${esc(a.id)}">${esc(a.asset_name)}</a>`,esc(a.campus),esc(visitTypeText(v)),esc(contractById(v.amc_contract)?.vendor||"–"),visitPill(v),esc(v.engineer||"–")],csv:[v.planned_date,v.id,a.asset_name,a.campus,visitTypeText(v),contractById(v.amc_contract)?.vendor||"",v.is_overdue?"Overdue":"Planned",v.engineer]};
  });
}
const REPORTS={
  coverage:{t:"Asset Coverage",cols:["Asset ID","Asset","Type","Campus","AMC","Vendor","AMC ends","Warranty","Last visit","Next visit"],note:"red = expired or ≤ 30 days · amber = 31–90 days · green = active (more than 90 days)"},
  renewals:{t:"Renewals Due",cols:["Type","Reference","Asset(s)","Campus","Vendor / provider","Ends on","Days left","Renewal status","Value incl. GST"],note:"AMC contracts and warranties ending in the next N days"},
  vsched:{t:"Visit Schedule",cols:["Planned date","Visit","Asset","Campus","Type","Vendor","Status","Engineer"],note:"overdue visits and visits planned in the next N days"}
};
function pReport(kind){
  const f=ST.rep[kind],R=REPORTS[kind],rows=reportRows(kind);
  const extra=kind==="renewals"?`${sel("r-days",[30,60,90,180,365].map(n=>[String(n),`Next ${n} days`]),String(f.days))}<label style="display:flex;gap:6px;align-items:center;margin:0"><input type="checkbox" id="r-exp" ${f.expired?"checked":""}> Include already ended</label>`
    :kind==="vsched"?sel("r-days",[7,15,30,60,90].map(n=>[String(n),`Upcoming ${n} days`]),String(f.days)):"";
  return `<div class="vh"><span class="dt">Script Report</span><span class="sp"></span><button class="btn sm" id="r-xls">${IC.csv}${CFG.proto?"Copy for Excel":"Download Excel"}</button></div>
  <div class="toolbar">${sel("r-campus",campusesOf(A()),f.campus,"All campuses")}${sel("r-type",ASSET_TYPES,f.type,"All asset types")}${extra}</div>
  <p class="small" style="margin:-4px 0 10px">${esc(R.note)}</p>
  <div class="tw"><table><thead><tr>${R.cols.map(c=>`<th>${esc(c)}</th>`).join("")}</tr></thead><tbody>
  ${rows.length?rows.map(r=>`<tr class="${r.cls?"row-"+r.cls:""}">${r.cells.map((c,i)=>`<td class="${/^\d|₹/.test(String(c).replace(/<[^>]*>/g,""))&&!/[A-Za-z]{4,}/.test(String(c).replace(/<[^>]*>/g,""))?"n":""}">${c}</td>`).join("")}</tr>`).join(""):`<tr><td colspan="${R.cols.length}" class="empty">Nothing to show for these filters.</td></tr>`}
  </tbody></table></div><p class="small">${rows.length} row(s)</p>`;
}
function bindReport(kind){
  const f=ST.rep[kind];
  $("#r-campus").addEventListener("input",e=>{f.campus=e.target.value;render()});
  $("#r-type").addEventListener("input",e=>{f.type=e.target.value;render()});
  const d=$("#r-days");if(d)d.addEventListener("input",e=>{f.days=+e.target.value;render()});
  const x=$("#r-exp");if(x)x.addEventListener("input",e=>{f.expired=e.target.checked;render()});
  $("#r-xls").addEventListener("click",async()=>{
    const rows=reportRows(kind),data=[REPORTS[kind].cols,...rows.map(r=>r.csv.map(v=>v==null?"":v))];
    try{toast(await BE.exportXlsx(REPORTS[kind].t,data))}
    catch(err){toast(err.message||"Could not make the Excel file",true)}
  });
}


