/* ============ searchable dropdowns ============
   Every <select> opens a small panel with a search box instead of the native list, so an entry is found by typing
   any part of its name. Same behaviour as the other apps (Water Supply O&M). */
const SS_MIN=2,SS_MAX=200;
let ssBox=null,ssSel=null,ssOpts=[],ssIdx=-1,ssTap=0,ssTotal=0;
const SSHOST=CFG.proto?document.body:R;
const ssBig=el=>!!el&&el.tagName==="SELECT"&&!el.disabled&&!el.multiple&&el.options.length>=SS_MIN&&!el.closest(".ss");
function ssClose(){if(ssBox)ssBox.remove();ssBox=null;ssSel=null;ssOpts=[];ssIdx=-1;ssTotal=0}
function ssPlace(){
  if(!ssBox||!ssSel)return;
  const r=ssSel.getBoundingClientRect(),w=Math.max(r.width,220),h=ssBox.offsetHeight;
  let left=Math.min(r.left,window.innerWidth-w-8);if(left<8)left=8;
  let top=r.bottom+4;if(top+h>window.innerHeight-8)top=Math.max(8,r.top-h-4);
  ssBox.style.left=left+"px";ssBox.style.top=top+"px";ssBox.style.width=w+"px";
}
function ssMark(label,q){
  const i=q?label.toLowerCase().indexOf(q):-1;
  return i<0?esc(label):esc(label.slice(0,i))+"<b>"+esc(label.slice(i,i+q.length))+"</b>"+esc(label.slice(i+q.length));
}
function ssPaint(){
  const q=ssBox.querySelector(".ss-q").value.trim().toLowerCase();
  const all=Array.from(ssSel.options).map((o,i)=>({i,label:o.text,on:o.selected,dis:o.disabled}))
    .filter(o=>!o.dis&&(q?o.label.toLowerCase().indexOf(q)>=0:true));
  ssTotal=all.length;ssOpts=all.slice(0,SS_MAX);
  if(ssIdx<0||!ssOpts[ssIdx])ssIdx=Math.max(0,ssOpts.findIndex(o=>o.on));
  ssBox.querySelector(".ss-list").innerHTML=ssOpts.length
    ?ssOpts.map((o,k)=>`<div class="ss-o${o.on?" cur":""}${k===ssIdx?" on":""}${o.label?"":" none"}" role="option" data-k="${k}">${o.label?ssMark(o.label,q):"(none)"}</div>`).join("")+(ssTotal>SS_MAX?`<div class="ss-none">${ssTotal-SS_MAX} more. Type to narrow the list.</div>`:"")
    :`<div class="ss-none">Nothing matches</div>`;
  const el=ssBox.querySelector(".ss-o.on");if(el&&el.scrollIntoView)el.scrollIntoView({block:"nearest"});
}
function ssPick(k){
  const o=ssOpts[k],sel=ssSel;if(!o||!sel)return;
  ssClose();
  if(sel.selectedIndex!==o.i){sel.selectedIndex=o.i;sel.dispatchEvent(new Event("input",{bubbles:true}));sel.dispatchEvent(new Event("change",{bubbles:true}))}
  sel.focus();
}
function ssOpen(sel,first){
  if(ssSel===sel){ssClose();return}
  ssClose();ssSel=sel;
  ssBox=document.createElement("div");ssBox.className="ss";
  const lab=sel.getAttribute("aria-label")||(sel.id&&document.querySelector(`label[for="${sel.id}"]`)?document.querySelector(`label[for="${sel.id}"]`).textContent:"")||"list";
  ssBox.innerHTML=`<input class="ss-q" type="text" placeholder="Search…" autocomplete="off" aria-label="Search ${esc(lab)}"><div class="ss-list" role="listbox"></div>`;
  SSHOST.appendChild(ssBox);
  const q=ssBox.querySelector(".ss-q");if(first)q.value=first;
  ssPaint();ssPlace();q.focus();
  q.addEventListener("input",()=>{ssIdx=-1;ssPaint();ssPlace()});
  q.addEventListener("keydown",e=>{
    if(e.key==="Escape"){e.preventDefault();e.stopPropagation();const s=ssSel;ssClose();if(s)s.focus()}
    else if(e.key==="ArrowDown"){e.preventDefault();ssIdx=Math.min(ssOpts.length-1,ssIdx+1);ssPaint()}
    else if(e.key==="ArrowUp"){e.preventDefault();ssIdx=Math.max(0,ssIdx-1);ssPaint()}
    else if(e.key==="Enter"){e.preventDefault();e.stopPropagation();ssPick(ssIdx)}
  });
  ssBox.querySelector(".ss-list").addEventListener("mousedown",e=>{const d=e.target.closest(".ss-o");if(!d)return;e.preventDefault();ssPick(Number(d.dataset.k))});
}
R.addEventListener("mousedown",e=>{
  const s=e.target.closest&&e.target.closest("select");
  if(ssBox&&!e.target.closest(".ss")&&s!==ssSel)ssClose();
  if(ssBig(s)){e.preventDefault();ssTap=Date.now();ssOpen(s)}
},true);
R.addEventListener("click",e=>{
  const s=e.target.closest&&e.target.closest("select");
  if(ssBig(s)){e.preventDefault();if(!ssBox&&Date.now()-ssTap>400)ssOpen(s)}
},true);
R.addEventListener("keydown",e=>{
  if(ssBox||!ssBig(e.target))return;
  const ch=e.key.length===1&&!e.ctrlKey&&!e.metaKey&&!e.altKey;
  if(ch||e.key==="Enter"||e.key===" "||e.key==="ArrowDown"||e.key==="ArrowUp"){e.preventDefault();ssOpen(e.target,ch?e.key:"")}
});
R.addEventListener("scroll",()=>{if(ssBox)ssPlace()},true);
window.addEventListener("resize",()=>{if(ssBox)ssClose()});

/* ============ clickable links ============
   A linked record opens on click: an asset or contract inside this app, a supplier, work order, purchase document
   or company in the desk (new tab). */
const LINK_TARGET={
  asset:{k:"asset"},amc_contract:{k:"contract"},previous_contract:{k:"contract"},
  work_order:{dt:"Work Order Contract"},vendor:{dt:"Supplier"},supplier:{dt:"Supplier"},purchase_order:{dt:"Purchase Order"},
  purchase_invoice:{dt:"Purchase Invoice"},erpnext_asset:{dt:"Asset"},campus:{dt:"Company"}
};
function openLink(key,val){
  const t=LINK_TARGET[key];if(!t||!val)return;
  if(t.k==="asset"){closeForm();go("#asset/"+val);return}
  if(t.k==="contract"){openForm("contract",val);return}
  if(CFG.proto){toast(`Would open ${t.dt} ${val} in ERPNext`);return}
  window.open(`/app/${erpSlug(t.dt)}/${encodeURIComponent(val)}`,"_blank","noopener");
}
/* a dropdown with an "Other" option shows a text box for what Other means */
function syncOther(focusFor){
  $$("#mForm [data-other-for]").forEach(w=>{
    const s=$("#f_"+w.dataset.otherFor),on=!!s&&s.value==="Other",i=w.querySelector("input"),was=!w.hidden;
    w.hidden=!on;
    if(!on&&i)i.value="";
    if(on&&!was&&focusFor===w.dataset.otherFor&&i)setTimeout(()=>i.focus(),0);
  });
}
function syncLinkBtns(){
  $$("#mForm .lkopen").forEach(b=>{const s=$("#f_"+b.dataset.lk);b.hidden=!(s&&s.value)});
}

